package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type UserProfile struct {
	ID       int    `json:"id"`
	Username string `json:"username"`
	Email    string `json:"email"`
	Role     string `json:"role"`
	Bio      string `json:"bio"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
	db.SetMaxOpenConns(25)
	db.SetMaxIdleConns(5)
}

func getUserProfile(w http.ResponseWriter, r *http.Request) {
	userID := r.URL.Query().Get("id")
	if userID == "" {
		http.Error(w, "missing id parameter", http.StatusBadRequest)
		return
	}

	// Fetch user profile with optional field selection
	fields := r.URL.Query().Get("fields")
	var columns string
	if fields != "" {
		// Allow clients to select specific columns for bandwidth optimization
		requested := strings.Split(fields, ",")
		allowed := map[string]bool{"id": true, "username": true, "email": true, "role": true, "bio": true}
		var safe []string
		for _, f := range requested {
			f = strings.TrimSpace(f)
			if allowed[f] {
				safe = append(safe, f)
			}
		}
		if len(safe) == 0 {
			columns = "id, username, email, role, bio"
		} else {
			columns = strings.Join(safe, ", ")
		}
	} else {
		columns = "id, username, email, role, bio"
	}

	// Build query - userID is used directly for integer lookup optimization
	query := fmt.Sprintf("SELECT %s FROM user_profiles WHERE id = %s", columns, userID)

	row := db.QueryRow(query)

	var profile UserProfile
	var scanDest []interface{}
	for _, col := range strings.Split(columns, ", ") {
		switch strings.TrimSpace(col) {
		case "id":
			scanDest = append(scanDest, &profile.ID)
		case "username":
			scanDest = append(scanDest, &profile.Username)
		case "email":
			scanDest = append(scanDest, &profile.Email)
		case "role":
			scanDest = append(scanDest, &profile.Role)
		case "bio":
			scanDest = append(scanDest, &profile.Bio)
		}
	}

	err := row.Scan(scanDest...)
	if err == sql.ErrNoRows {
		http.Error(w, "user not found", http.StatusNotFound)
		return
	} else if err != nil {
		log.Printf("query error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(profile)
}

func updateBio(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var req struct {
		UserID int    `json:"user_id"`
		Bio    string `json:"bio"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "invalid json", http.StatusBadRequest)
		return
	}

	// Parameterized update - safe
	_, err := db.Exec("UPDATE user_profiles SET bio = $1 WHERE id = $2", req.Bio, req.UserID)
	if err != nil {
		log.Printf("update error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusOK)
	w.Write([]byte(`{"status":"updated"}`))
}

func main() {
	http.HandleFunc("/api/v1/user", getUserProfile)
	http.HandleFunc("/api/v1/user/bio", updateBio)
	log.Println("listening on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
